1	/**
2	 * DispatchStreamConsumer — owns the dispatch Redis Stream.
3	 *
4	 * Consumes jobs from the dispatch stream via XREADGROUP (consumer group),
5	 * redelivers stuck entries via XAUTOCLAIM, and routes jobs to the DLQ
6	 * after maxDeliveries failed attempts.
7	 *
8	 * Per-handle idempotency:
9	 *   Before docker run, acquires: SET dispatch:lock:<handle> <owner> NX PX <ttl>
10	 *   Only the lock winner spawns; losers skip + XACK to remove from their PEL.
11	 *   The platform.handle=<handle> label check is a cheap post-spawn backstop.
12	 *
13	 * DLQ handling:
14	 *   After maxDeliveries, the entry is moved to DISPATCH_DLQ_KEY and a
15	 *   synthetic "failed" completion is posted to the broker /callback, routing
16	 *   the terminal failure through the normal completion path.
17	 *
18	 * Global spawn cap:
19	 *   Before spawning, reads broker GET /registry-size and skips if at cap.
20	 *   On cap-exceeded, the entry is left pending (XREADGROUP will redeliver).
21	 */
22	
23	import * as http from "node:http";
24	import * as https from "node:https";
25	import { randomUUID } from "node:crypto";
26	import type { RedisClientType } from "redis";
27	import {
28	  DISPATCH_STREAM_KEY,
29	  DISPATCH_CONSUMER_GROUP,
30	  DISPATCH_DLQ_KEY,
31	  type DispatchJob,
32	} from "@workflow/runtime-abi";
33	import type { DockerSpawner } from "./spawner.js";
34	import type { CredentialAdapter } from "./credential.js";
35	
36	// ── Types ─────────────────────────────────────────────────────────────────────
37	
38	export interface ConsumerOpts {
39	  redis: RedisClientType;
40	  spawner: DockerSpawner;
41	  credential: CredentialAdapter;
42	  brokerUrl: string;
43	  consumerId: string;
44	  maxConcurrent: number;
45	  maxDeliveries: number;
46	  spawnLockTtlMs: number;
47	  pollBlockMs: number;
48	  xautoclaimMinIdleMs: number;
49	  batchSize: number;
50	}
51	
52	interface StreamEntry {
53	  id: string;
54	  message: Record<string, string>;
55	}
