121	// ── Consumer ──────────────────────────────────────────────────────────────────
122	
123	export class DispatchStreamConsumer {
124	  private readonly redis: RedisClientType;
125	  private readonly spawner: DockerSpawner;
126	  private readonly credential: CredentialAdapter;
127	  private readonly brokerUrl: string;
128	  private readonly consumerId: string;
129	  private readonly maxConcurrent: number;
130	  private readonly maxDeliveries: number;
131	  private readonly spawnLockTtlMs: number;
132	  private readonly pollBlockMs: number;
133	  private readonly xautoclaimMinIdleMs: number;
134	  private readonly batchSize: number;
135	
136	  private stopped = false;
137	
138	  constructor(opts: ConsumerOpts) {
139	    this.redis = opts.redis;
140	    this.spawner = opts.spawner;
141	    this.credential = opts.credential;
142	    this.brokerUrl = opts.brokerUrl;
143	    this.consumerId = opts.consumerId;
144	    this.maxConcurrent = opts.maxConcurrent;
145	    this.maxDeliveries = opts.maxDeliveries;
146	    this.spawnLockTtlMs = opts.spawnLockTtlMs;
147	    this.pollBlockMs = opts.pollBlockMs;
148	    this.xautoclaimMinIdleMs = opts.xautoclaimMinIdleMs;
149	    this.batchSize = opts.batchSize;
150	  }
151	
152	  /**
153	   * Ensure the consumer group exists on the dispatch stream.
154	   * Creates the stream + group if absent ($ = only new messages).
155	   */
156	  async ensureConsumerGroup(): Promise<void> {
157	    try {
158	      await this.redis.xGroupCreate(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, "$", {
159	        MKSTREAM: true,
160	      });
161	      emit({ type: "consumer_group_created", group: DISPATCH_CONSUMER_GROUP });
162	    } catch (err) {
163	      // BUSYGROUP: group already exists — ignore.
164	      if (String(err).includes("BUSYGROUP")) return;
165	      throw err;
166	    }
167	  }
168	
169	  stop(): void {
170	    this.stopped = true;
171	  }
172	
173	  /**
174	   * Run the main dispatch loop until stop() is called.
175	   *
176	   * Each iteration:
177	   *   1. XAUTOCLAIM stuck pending entries.
178	   *   2. XREADGROUP for new entries.
179	   *   3. Process all collected entries.
180	   */
181	  async run(): Promise<void> {
182	    await this.ensureConsumerGroup();
183	
184	    while (!this.stopped) {
185	      try {
186	        // 1. Reclaim stuck entries (pending longer than xautoclaimMinIdleMs).
187	        const reclaimed = await this._xautoclaim();
188	
189	        // 2. Read new entries (blocks up to pollBlockMs if none pending).
190	        const fresh = await this._xreadgroup();
191	
192	        const entries = [...reclaimed, ...fresh];
193	        if (entries.length > 0) {
194	          await Promise.all(entries.map((e) => this._processEntry(e)));
195	        }
196	      } catch (err) {
197	        emit({ type: "consumer_loop_error", error: String(err) });
198	        // Brief back-off to avoid a tight error loop.
199	        await new Promise((r) => setTimeout(r, 1_000));
200	      }
201	    }
202	  }
203	
204	  // ── Internal ───────────────────────────────────────────────────────────────
205	
206	  private async _xautoclaim(): Promise<StreamEntry[]> {
207	    try {
208	      const result = await (this.redis as any).xAutoClaim(
209	        DISPATCH_STREAM_KEY,
210	        DISPATCH_CONSUMER_GROUP,
211	        this.consumerId,
212	        this.xautoclaimMinIdleMs,
213	        "0-0",
214	        { COUNT: this.batchSize },
215	      );
216	      // node-redis v4+ returns { nextId, messages }
217	      const messages: Array<{ id: string; message: Record<string, string> }> =
218	        result?.messages ?? [];
219	      return messages.map((m) => ({ id: m.id, message: m.message }));
220	    } catch (err) {
221	      // XAUTOCLAIM fails if the stream doesn't exist yet.
222	      if (String(err).includes("ERR no such key")) return [];
223	      emit({ type: "xautoclaim_error", error: String(err) });
224	      return [];
225	    }
226	  }
227	
228	  private async _xreadgroup(): Promise<StreamEntry[]> {
229	    try {
230	      const results = await this.redis.xReadGroup(
231	        DISPATCH_CONSUMER_GROUP,
232	        this.consumerId,
233	        [{ key: DISPATCH_STREAM_KEY, id: ">" }],
234	        { COUNT: this.batchSize, BLOCK: this.pollBlockMs },
235	      );
236	      if (!results || results.length === 0) return [];
237	      const entries: StreamEntry[] = [];
238	      for (const stream of results) {
239	        for (const msg of stream.messages) {
240	          entries.push({ id: msg.id, message: msg.message as Record<string, string> });
241	        }
242	      }
243	      return entries;
244	    } catch (err) {
245	      emit({ type: "xreadgroup_error", error: String(err) });
246	      return [];
247	    }
248	  }
249	
250	  /**
251	   * Get the delivery count for a pending entry.
252	   * Returns 1 if XPENDING-RANGE is unavailable (treat as first delivery).
253	   */
254	  async _getDeliveryCount(entryId: string): Promise<number> {
255	    try {
256	      const pending = await this.redis.xPendingRange(
257	        DISPATCH_STREAM_KEY,
258	        DISPATCH_CONSUMER_GROUP,
259	        entryId,
260	        entryId,
261	        1,
262	      );
263	      if (pending.length === 0) return 1;
264	      // node-redis v4+ uses `deliveriesCounter` for the delivery count field.
265	      const entry = pending[0] as { deliveriesCounter?: number; deliveryCount?: number };
266	      return entry.deliveriesCounter ?? entry.deliveryCount ?? 1;
267	    } catch {
268	      return 1;
269	    }
270	  }
271	
272	  private async _processEntry(entry: StreamEntry): Promise<void> {
273	    const { id, message } = entry;
274	
275	    // Parse DispatchJob from the stream entry.
276	    let job: DispatchJob;
277	    try {
278	      const raw = message.job;
279	      if (!raw) throw new Error("missing 'job' field in stream entry");
280	      job = JSON.parse(raw) as DispatchJob;
281	    } catch (err) {
282	      emit({ type: "dispatch_parse_error", entry_id: id, error: String(err) });
283	      // Malformed entry: ACK to discard it rather than looping forever.
284	      await this._xack(id);
285	      return;
286	    }
287	
288	    // Check delivery count against maxDeliveries.
289	    const deliveryCount = await this._getDeliveryCount(id);
290	    if (deliveryCount > this.maxDeliveries) {
291	      emit({
292	        type: "dispatch_dlq",
293	        handle: job.handle,
294	        entry_id: id,
295	        delivery_count: deliveryCount,
296	        max_deliveries: this.maxDeliveries,
297	      });
298	      await this._moveToDlq(id, job);
299	      return;
300	    }
301	
302	    // Check global spawn cap via broker registry-size.
303	    const registrySize = await this._getRegistrySize();
304	    if (registrySize >= this.maxConcurrent) {
305	      emit({
306	        type: "dispatch_cap_exceeded",
307	        handle: job.handle,
308	        registry_size: registrySize,
309	        max_concurrent: this.maxConcurrent,
310	      });
311	      // Leave in PEL; XAUTOCLAIM will redeliver when capacity frees up.
312	      return;
313	    }
314	
315	    // Acquire per-handle spawn lock before docker run (closes TOCTOU window).
316	    const lockOwner = randomUUID();
317	    const lockKey = `dispatch:lock:${job.handle}`;
318	    const lockAcquired = await this._acquireSpawnLock(lockKey, lockOwner);
319	    if (!lockAcquired) {
320	      emit({
321	        type: "dispatch_lock_lost",
322	        handle: job.handle,
323	        entry_id: id,
324	      });
325	      // Another dispatcher won; XACK to remove from our PEL.
326	      await this._xack(id);
327	      return;
328	    }
329	
330	    // Post-spawn backstop: check if a container already exists for this handle.
331	    const existingId = await this.spawner.findExistingContainer(job.handle);
332	    if (existingId !== null) {
333	      emit({
334	        type: "dispatch_duplicate_container",
335	        handle: job.handle,
336	        container_id: existingId,
337	        entry_id: id,
338	      });
339	      await this._releaseSpawnLock(lockKey, lockOwner);
340	      await this._xack(id);
341	      return;
342	    }
343	
344	    // Resolve credentials — dispatcher is the sole credential holder.
345	    let githubToken: string;
346	    let sshPrivateKey: string;
347	    try {
348	      [githubToken, sshPrivateKey] = await Promise.all([
349	        this.credential.getGitHubToken(),
350	        this.credential.getSshPrivateKey(),
351	      ]);
352	    } catch (err) {
353	      emit({ type: "dispatch_credential_error", handle: job.handle, error: String(err) });
354	      await this._releaseSpawnLock(lockKey, lockOwner);
355	      return; // Leave in PEL for redelivery.
356	    }
357	
358	    // Spawn the executor container.
359	    try {
360	      const { containerId } = await this.spawner.spawn(job, githubToken, sshPrivateKey);
361	      emit({
362	        type: "dispatch_spawn_ok",
363	        handle: job.handle,
364	        task_id: job.task_id,
365	        feature_id: job.feature_id,
366	        container_id: containerId,
367	        entry_id: id,
368	      });
369	      // XACK after successful spawn.
370	      await this._xack(id);
371	    } catch (err) {
372	      emit({
373	        type: "dispatch_spawn_error",
374	        handle: job.handle,
375	        task_id: job.task_id,
376	        error: String(err),
377	        entry_id: id,
378	      });
379	      // Release lock so another instance can retry.
380	      await this._releaseSpawnLock(lockKey, lockOwner);
381	      // Leave in PEL; XAUTOCLAIM will redeliver.
382	    }
383	    // Lock is intentionally kept until container starts (not released on success):
384	    // the container label becomes the post-spawn guard; the lock prevents
385	    // the TOCTOU window during the spawning gap.
386	  }
387	
388	  private async _xack(entryId: string): Promise<void> {
389	    try {
390	      await this.redis.xAck(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, entryId);
391	    } catch (err) {
392	      emit({ type: "xack_error", entry_id: entryId, error: String(err) });
393	    }
394	  }
395	
396	  /**
397	   * Move a job to the DLQ and post a synthetic failed completion to the broker.
398	   * The orchestrator learns about the terminal failure through the normal
399	   * completion path — no dispatched-vs-not bookkeeping at the orchestrator.
400	   */
401	  private async _moveToDlq(entryId: string, job: DispatchJob): Promise<void> {
402	    try {
403	      await this.redis.xAdd(DISPATCH_DLQ_KEY, "*", { job: JSON.stringify(job) });
404	    } catch (err) {
405	      emit({ type: "dlq_write_error", handle: job.handle, error: String(err) });
406	    }
407	
408	    // Post synthetic failed completion so the orchestrator learns through /callback.
409	    const callbackBody = JSON.stringify({
410	      handle: job.handle,
411	      nonce: job.nonce,
412	      result: {
413	        terminal_status: "failed",
414	        blocked_reason: `dispatch_dlq_after_${this.maxDeliveries}_deliveries`,
415	      },
416	    });
417	
418	    try {
419	      await httpPost(`${job.callback_url}`, callbackBody);
420	      emit({
421	        type: "dispatch_dlq_callback_posted",
422	        handle: job.handle,
423	        callback_url: job.callback_url,
424	      });
425	    } catch (err) {
426	      emit({
427	        type: "dispatch_dlq_callback_error",
428	        handle: job.handle,
429	        error: String(err),
430	      });
431	    }
432	
433	    // XACK after routing to DLQ.
434	    await this._xack(entryId);
435	  }
436	
437	  /**
438	   * Read the current in-flight count from the broker GET /registry-size.
439	   * Returns maxConcurrent on error so we conservatively skip spawning.
440	   */
441	  async _getRegistrySize(): Promise<number> {
442	    try {
443	      const body = await httpGet(`${this.brokerUrl}/registry-size`);
444	      const parsed = JSON.parse(body) as { size?: number };
445	      return typeof parsed.size === "number" ? parsed.size : this.maxConcurrent;
446	    } catch {
447	      return this.maxConcurrent;
448	    }
449	  }
450	
451	  /**
452	   * Acquire a per-handle spawn lock using SET NX PX.
453	   * Returns true if the lock was acquired.
454	   */
455	  async _acquireSpawnLock(lockKey: string, lockOwner: string): Promise<boolean> {
456	    const result = await this.redis.set(lockKey, lockOwner, {
457	      NX: true,
458	      PX: this.spawnLockTtlMs,
459	    });
460	    return result === "OK";
461	  }
462	
463	  /**
464	   * Release the spawn lock only if we still own it (check-and-delete via GET).
465	   * Best-effort: if the key expired, nothing to do.
466	   */
467	  async _releaseSpawnLock(lockKey: string, lockOwner: string): Promise<void> {
468	    try {
469	      const current = await this.redis.get(lockKey);
470	      if (current === lockOwner) {
471	        await this.redis.del(lockKey);
472	      }
473	    } catch {
474	      // Best-effort.
475	    }
476	  }
477	}
