47	    consumerId: config.consumerId,
48	    maxConcurrent: config.maxConcurrent,
49	    maxDeliveries: config.maxDeliveries,
50	    spawnLockTtlMs: config.spawnLockTtlMs,
51	    pollBlockMs: config.pollBlockMs,
52	    xautoclaimMinIdleMs: config.xautoclaimMinIdleMs,
53	    batchSize: config.batchSize,
54	  });
55	
56	  let stopping = false;
57	
58	  async function shutdown(signal: string): Promise<void> {
59	    if (stopping) return;
60	    stopping = true;
61	    emit({ type: "dispatcher_stopping", signal });
62	    consumer.stop();
63	    await redis.quit();
64	    emit({ type: "dispatcher_stopped" });
