/**
 * EnvCredentialAdapter — reads credentials from environment variables.
 *
 * The dispatcher is the sole credential holder on the local-docker path.
 * It injects GITHUB_TOKEN and SSH_PRIVATE_KEY at container spawn time;
 * these values are never placed on the dispatch queue.
 */

export interface CredentialAdapter {
  getGitHubToken(): Promise<string>;
  getSshPrivateKey(): Promise<string>;
}

export class EnvCredentialAdapter implements CredentialAdapter {
  private readonly env: NodeJS.ProcessEnv;

  constructor(env: NodeJS.ProcessEnv = process.env) {
    this.env = env;
  }

  async getGitHubToken(): Promise<string> {
    return this.env.GITHUB_TOKEN ?? "";
  }

  async getSshPrivateKey(): Promise<string> {
    return this.env.SSH_PRIVATE_KEY ?? "";
  }
}

