1	/**
2	 * Unit tests for DispatchStreamConsumer.
3	 *
4	 * All Redis and spawner interactions are faked — no real Redis or Docker required.
5	 *
6	 * Scenarios:
7	 *   1. Happy path: job consumed, container spawned, XACK'd.
8	 *   2. Spawn lock: exactly one winner spawns when two dispatchers race.
9	 *   3. DLQ routing: job moved to DLQ + synthetic /callback after maxDeliveries.
10	 *   4. Cap enforcement: spawn skipped when registry-size >= maxConcurrent.
11	 *   5. XAUTOCLAIM redelivery: stuck entries are reclaimed and processed.
12	 *   6. Duplicate container: label-backstop check prevents second spawn.
13	 *   7. Malformed entry: ACK'd and discarded without crashing.
14	 */
15	
16	// vi.mock is hoisted by vitest before imports — node:http.request is replaced
17	// with vi.fn() so the _moveToDlq direct-test can configure it per-test without
18	// needing a real HTTP server.  All other tests mock _getRegistrySize / _moveToDlq
19	// at the method level, so they never reach http.request.
20	vi.mock("node:http", () => ({ request: vi.fn() }));
21	
22	import { describe, it, expect, beforeEach, vi } from "vitest";
23	import { randomUUID } from "node:crypto";
24	import * as nodeHttp from "node:http";
25	import { DispatchStreamConsumer, type ConsumerOpts } from "../src/consumer.js";
26	import type { DispatchJob } from "@workflow/runtime-abi";
27	import { DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, DISPATCH_DLQ_KEY } from "@workflow/runtime-abi";
28	import type { DockerSpawner } from "../src/spawner.js";
29	import type { CredentialAdapter } from "../src/credential.js";
30	
31	// ── Fake implementations ──────────────────────────────────────────────────────
32	
33	function makeJob(overrides?: Partial<DispatchJob>): DispatchJob {
34	  return {
35	    handle: randomUUID(),
36	    nonce: randomUUID(),
37	    kind: "impl",
38	    task_id: "T4",
39	    feature_id: "standalone-executor-hardening",
40	    workspace_id: "ws-test",
41	    task_repo_url: "git@github.com:org/repo.git",
42	    task_repo_branch: "feature/test-T4",
43	    task_base_branch: "feature/standalone-executor-hardening",
44	    task_repo_base_branch: "main",
45	    mgmt_repo_url: "git@github.com:org/workspace.git",
46	    executor_workdir: "/workspace",
47	    callback_url: "http://broker:7000/callback",
48	    enqueued_at: new Date().toISOString(),
49	    ...overrides,
50	  };
51	}
52	
53	function makeEntry(job: DispatchJob, id?: string): { id: string; message: Record<string, string> } {
54	  return { id: id ?? `${Date.now()}-0`, message: { job: JSON.stringify(job) } };
55	}
56	
57	interface FakeRedis {
58	  // Collected calls for assertion
59	  xAddCalls: Array<{ key: string; id: string; fields: Record<string, string> }>;
60	  xAckCalls: Array<{ key: string; group: string; id: string }>;
61	  xPendingRangeResults: Map<string, { deliveryCount: number }[]>;
62	  setCalls: Array<{ key: string; value: string; opts: { NX?: boolean; PX?: number } }>;
63	  setResults: Map<string, string | null>;
64	  getCalls: string[];
65	  getResults: Map<string, string | null>;
66	  delCalls: string[];
67	
68	  // Behaviour overrides
69	  xAdd: ReturnType<typeof vi.fn>;
70	  xAck: ReturnType<typeof vi.fn>;
71	  xPendingRange: ReturnType<typeof vi.fn>;
72	  set: ReturnType<typeof vi.fn>;
73	  get: ReturnType<typeof vi.fn>;
74	  del: ReturnType<typeof vi.fn>;
75	  xGroupCreate: ReturnType<typeof vi.fn>;
76	  xReadGroup: ReturnType<typeof vi.fn>;
77	  xAutoClaim: ReturnType<typeof vi.fn>;
78	}
79	
80	function makeFakeRedis(opts?: {
81	  pendingByEntryId?: Map<string, number>;
82	  setResultFn?: (key: string) => string | null;
83	}): FakeRedis {
84	  const xAddCalls: FakeRedis["xAddCalls"] = [];
85	  const xAckCalls: FakeRedis["xAckCalls"] = [];
86	  const setCalls: FakeRedis["setCalls"] = [];
87	  const getCalls: string[] = [];
88	  const delCalls: string[] = [];
89	
90	  const r: FakeRedis = {
91	    xAddCalls,
92	    xAckCalls,
93	    xPendingRangeResults: new Map(),
94	    setCalls,
95	    setResults: new Map(),
96	    getCalls,
97	    getResults: new Map(),
98	    delCalls,
99	
100	    xAdd: vi.fn(async (key: string, id: string, fields: Record<string, string>) => {
101	      xAddCalls.push({ key, id, fields });
102	      return "1-0";
103	    }),
104	    xAck: vi.fn(async (key: string, group: string, id: string) => {
105	      xAckCalls.push({ key, group, id });
106	      return 1;
107	    }),
108	    xPendingRange: vi.fn(async (key: string, group: string, start: string, end: string, count: number) => {
109	      const entryId = start; // our call uses same start=end=entryId
110	      const deliveryCount = opts?.pendingByEntryId?.get(entryId) ?? 1;
111	      return [{ id: entryId, deliveryCount, consumer: "test", idle: 100 }];
112	    }),
113	    set: vi.fn(async (key: string, value: string, setOpts: { NX?: boolean; PX?: number }) => {
114	      setCalls.push({ key, value, opts: setOpts });
115	      if (opts?.setResultFn) return opts.setResultFn(key);
116	      // Default: always grant the lock (return "OK")
117	      return "OK";
118	    }),
119	    get: vi.fn(async (key: string) => {
120	      getCalls.push(key);
121	      return null;
122	    }),
123	    del: vi.fn(async (key: string) => {
124	      delCalls.push(key);
125	      return 1;
126	    }),
127	    xGroupCreate: vi.fn(async () => "OK"),
128	    xReadGroup: vi.fn(async () => []),
129	    xAutoClaim: vi.fn(async () => ({ nextId: "0-0", messages: [] })),
130	  };
131	  return r;
132	}
133	
134	function makeFakeSpawner(opts?: {
135	  existingHandle?: string;
136	  spawnError?: Error;
137	}): DockerSpawner & { spawnCalls: DispatchJob[] } {
138	  const spawnCalls: DispatchJob[] = [];
139	  return {
140	    spawnCalls,
141	    findExistingContainer: vi.fn(async (handle: string) => {
142	      return opts?.existingHandle === handle ? "fake-container-id" : null;
143	    }),
144	    spawn: vi.fn(async (job: DispatchJob) => {
145	      if (opts?.spawnError) throw opts.spawnError;
146	      spawnCalls.push(job);
147	      return { containerId: `container-${job.handle}` };
148	    }),
149	  } as unknown as DockerSpawner & { spawnCalls: DispatchJob[] };
150	}
151	
152	function makeFakeCredential(): CredentialAdapter {
153	  return {
154	    getGitHubToken: vi.fn(async () => "fake-token"),
155	    getSshPrivateKey: vi.fn(async () => "fake-key"),
156	  };
157	}
158	
159	const BASE_OPTS = {
160	  brokerUrl: "http://broker:7000",
161	  consumerId: "test-dispatcher",
162	  maxConcurrent: 5,
163	  maxDeliveries: 3,
164	  spawnLockTtlMs: 300_000,
165	  pollBlockMs: 100,
166	  xautoclaimMinIdleMs: 30_000,
167	  batchSize: 10,
168	};
169	
170	// ── Tests ─────────────────────────────────────────────────────────────────────
171	
172	describe("DispatchStreamConsumer", () => {
173	
174	  describe("_processEntry — happy path", () => {
175	    it("spawns container, then XACKs on success", async () => {
176	      const redis = makeFakeRedis();
177	      const spawner = makeFakeSpawner();
178	      const credential = makeFakeCredential();
179	
180	      const consumer = new DispatchStreamConsumer({
181	        redis: redis as any,
182	        spawner,
183	        credential,
184	        ...BASE_OPTS,
185	      });
186	
187	      // Stub _getRegistrySize to return 0 (cap not exceeded).
188	      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);
189	
190	      const job = makeJob();
191	      const entry = makeEntry(job, "100-0");
192	
193	      await (consumer as any)._processEntry(entry);
194	
195	      expect(spawner.spawnCalls).toHaveLength(1);
196	      expect(spawner.spawnCalls[0].handle).toBe(job.handle);
197	      expect(redis.xAckCalls).toHaveLength(1);
198	      expect(redis.xAckCalls[0].id).toBe("100-0");
199	    });
200	  });
201	
202	  describe("spawn lock — exactly one winner", () => {
203	    it("only one dispatcher spawns when two race on the same entry", async () => {
204	      // First dispatcher gets lock, second doesn't.
205	      let firstCall = true;
206	      const setResultFn = (_key: string): string | null => {
207	        if (firstCall) { firstCall = false; return "OK"; }
208	        return null; // second call loses
209	      };
210	
211	      const redis1 = makeFakeRedis({ setResultFn: () => "OK" });
212	      const redis2 = makeFakeRedis({ setResultFn: () => null });
213	
214	      const spawner1 = makeFakeSpawner();
215	      const spawner2 = makeFakeSpawner();
216	
217	      const c1 = new DispatchStreamConsumer({ redis: redis1 as any, spawner: spawner1, credential: makeFakeCredential(), ...BASE_OPTS });
218	      const c2 = new DispatchStreamConsumer({ redis: redis2 as any, spawner: spawner2, credential: makeFakeCredential(), ...BASE_OPTS });
219	
220	      vi.spyOn(c1, "_getRegistrySize" as any).mockResolvedValue(0);
221	      vi.spyOn(c2, "_getRegistrySize" as any).mockResolvedValue(0);
222	
223	      const job = makeJob();
224	      const entry = makeEntry(job, "200-0");
225	
226	      await Promise.all([
227	        (c1 as any)._processEntry(entry),
228	        (c2 as any)._processEntry(entry),
229	      ]);
230	
231	      // Exactly one spawner should have been called.
232	      const totalSpawns = spawner1.spawnCalls.length + spawner2.spawnCalls.length;
233	      expect(totalSpawns).toBe(1);
234	
235	      // Loser should have XACK'd to drop from its PEL.
236	      // c2 lost the lock → it XACK'd without spawning.
237	      expect(redis2.xAckCalls).toHaveLength(1);
238	    });
239	  });
240	
241	  describe("DLQ routing", () => {
242	    it("moves job to DLQ and posts synthetic /callback after maxDeliveries", async () => {
243	      const job = makeJob({ callback_url: "http://broker:7000/callback" });
244	      const entryId = "300-0";
245	      const pendingByEntryId = new Map([[entryId, 4]]); // > maxDeliveries=3
246	
247	      const redis = makeFakeRedis({ pendingByEntryId });
248	      const spawner = makeFakeSpawner();
249	
250	      const postedCallbacks: string[] = [];
251	      const consumer = new DispatchStreamConsumer({
252	        redis: redis as any,
253	        spawner,
254	        credential: makeFakeCredential(),
255	        ...BASE_OPTS,
256	      });
257	
258	      // Stub httpPost to capture synthetic callback.
259	      let dlqCallbackPosted = false;
260	      vi.spyOn(consumer as any, "_moveToDlq").mockImplementation(async (id: string, j: DispatchJob) => {
261	        dlqCallbackPosted = true;
262	        // Simulate XADD to DLQ + XACK.
263	        await redis.xAdd(DISPATCH_DLQ_KEY, "*", { job: JSON.stringify(j) });
264	        await redis.xAck(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, id);
265	      });
266	
267	      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);
268	
269	      const entry = makeEntry(job, entryId);
270	      await (consumer as any)._processEntry(entry);
271	
272	      expect(dlqCallbackPosted).toBe(true);
273	      // Should have written to DLQ stream.
274	      const dlqWrites = redis.xAddCalls.filter((c) => c.key === DISPATCH_DLQ_KEY);
275	      expect(dlqWrites).toHaveLength(1);
276	      // Should have XACK'd.
277	      expect(redis.xAckCalls.some((c) => c.id === entryId)).toBe(true);
278	      // Spawner should NOT have been called.
279	      expect(spawner.spawnCalls).toHaveLength(0);
280	    });
281	  });
282	
283	  describe("cap enforcement", () => {
284	    it("skips spawning when registry-size >= maxConcurrent", async () => {
285	      const redis = makeFakeRedis();
286	      const spawner = makeFakeSpawner();
287	      const consumer = new DispatchStreamConsumer({
288	        redis: redis as any,
289	        spawner,
290	        credential: makeFakeCredential(),
291	        ...BASE_OPTS,
292	        maxConcurrent: 3,
293	      });
294	
295	      // Registry already at cap.
296	      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(3);
297	
298	      const job = makeJob();
299	      const entry = makeEntry(job, "400-0");
300	      await (consumer as any)._processEntry(entry);
301	
302	      // No spawn, no XACK (left in PEL for later).
303	      expect(spawner.spawnCalls).toHaveLength(0);
304	      expect(redis.xAckCalls).toHaveLength(0);
305	    });
306	  });
307	
308	  describe("XAUTOCLAIM redelivery", () => {
309	    it("processes entries returned by XAUTOCLAIM", async () => {
310	      const job = makeJob();
311	      const reclaimedEntry = makeEntry(job, "500-0");
312	
313	      const redis = makeFakeRedis();
314	      // Return reclaimed entry on first xAutoClaim call.
315	      (redis.xAutoClaim as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
316	        nextId: "0-0",
317	        messages: [reclaimedEntry],
318	      });
319	
320	      const spawner = makeFakeSpawner();
321	      const consumer = new DispatchStreamConsumer({
322	        redis: redis as any,
323	        spawner,
324	        credential: makeFakeCredential(),
325	        ...BASE_OPTS,
326	      });
327	
328	      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);
