 */
export const DISPATCH_CONSUMER_GROUP = "dispatcher";

/**
 * Redis Stream key for the dispatch dead-letter queue (DLQ).
 * The dispatcher moves a job here after K failed redelivery attempts and
 * posts a synthetic `failed` completion to the broker `/callback` so the
--
export const DISPATCH_DLQ_KEY = "platform:dispatch:dlq";

/**
 * Credential-free payload the orchestrator XADDs to the dispatch stream.
 * The dispatcher reads this, injects credentials (GITHUB_TOKEN, SSH_PRIVATE_KEY),
 * and spawns the executor container.
--
export interface DispatchJob {
  /** Executor run identifier (UUID). Registered with the broker before enqueue. */
  handle: string;
  /** Single-use broker nonce; validated on /callback POST. */
  nonce: string;
  /** Discriminator: implementation run, review-fix, or rebase. */
